sys_script.script:
(function executeRule(current, previous) {
      // Validate: sync_filter_group is mandatory
      if (gs.nil(current.getValue('sync_filter_group'))) {
          gs.addErrorMessage('Sync Filter Group is required. Please select a group for this filter item.');
          current.setAbortAction(true);
          return;
      }

      // Validate: source_table and source_field are mandatory
      if (gs.nil(current.getValue('source_table'))) {
          gs.addErrorMessage('Source Table is required.');
          return;
      }   

      if (gs.nil(current.getValue('source_field'))) {
          gs.addErrorMessage('Source Field is required.');
          current.setAbortAction(true);
          return;
      }   

      // Check for duplicate: same group + same source_field
      var gr = new GlideRecord('x_illu2_illumio_illumio_workload_field_filter_item');
      gr.addQuery('sync_filter_group', current.getValue('sync_filter_group'));
      gr.addQuery('source_field', current.getValue('source_field'));
      gr.addQuery('sys_id', '!=', current.getUniqueValue());
      gr.setLimit(1);
      gr.query();

      if (gr.next()) {
          var groupName = current.sync_filter_group.getDisplayValue() || 'this group';
          var fieldName = current.source_field.getDisplayValue() || 'this field';

          gs.addErrorMessage(
              'Duplicate Source Field: "' + fieldName + '" already exists in group "' + groupName + '". ' +
              'Each field can only appear once per group. ' +
              'To filter by multiple values of the same field, create separate groups.'
          );
          current.setAbortAction(true);
      }   
  })(current, previous);
